import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'app-company-header',
  templateUrl: './company-header.component.html',
  styleUrls: ['./company-header.component.css']
})
export class CompanyHeaderComponent {
  @Input() avatar = '';
  @Input() showLogout = true;

  @Output() readonly logoutRequest = new EventEmitter<void>();

  onLogout(): void {
    this.logoutRequest.emit();
  }
}
<header class="topnav app">
  <div class="wrap">
    <a routerLink="/" class="brand">
      <span class="brand-dot"></span>HireHub
    </a>

    <nav class="nav-links app-links">
      <a routerLink="/company" routerLinkActive="active">Dashboard</a>
      <a routerLink="/company/post-job" routerLinkActive="active">Post a Job</a>
      <a routerLink="/company/manage-jobs" routerLinkActive="active">Manage Jobs</a>
      <a routerLink="/company/applicants" routerLinkActive="active">Applicants</a>
      <a routerLink="/company/profile" routerLinkActive="active">Company Profile</a>
    </nav>

    <ng-container *ngIf="showLogout; else avatarOnly">
      <div class="nav-actions">
        <div class="avatar" *ngIf="avatar">{{ avatar }}</div>
        <button class="btn btn-ghost-dark btn-sm" (click)="onLogout()">Logout</button>
      </div>
    </ng-container>
    <ng-template #avatarOnly>
      <div class="avatar">{{ avatar }}</div>
    </ng-template>
  </div>
</header>
